function get_time(){let e=new Date,t=e.getHours(),o=e.getMinutes(),n=e.getSeconds();0===n&&(get_date(),get_temperature(),get_weather()),t=t<10?"0"+t:t,o=o<10?"0"+o:o,n=n<10?"0"+n:n;let r=t+":"+o+":"+n;document.querySelector("#time").textContent=r,update_title()}function get_date(){let e=new Date,t=e.getFullYear(),o=e.getMonth()+1,n=e.getDate();o=o<10?"0"+o:o,n=n<10?"0"+n:n,document.querySelector("#date").textContent=t+"-"+o+"-"+n,document.querySelector("#day").textContent=day_names[e.getDay()]}function get_temperature(){fetch("https://corsproxy.io/?"+encodeURIComponent("https://home.sensibo.com/api/v2/pods/"+auth.sensibo_device+"/measurements?apiKey="+auth.sensibo_api_key),{method:"GET",cache:"no-store"}).then(e=>{if(e.ok)return e.json();throw"Error"}).then(e=>{"success"==e.status&&(document.querySelector("#temperature").textContent=e.result[0].temperature+" °C")}).catch(e=>{console.log(e)})}function get_weather(){fetch("https://api.openweathermap.org/data/2.5/weather?id="+auth.openweathermap_city_id+"&units=metric&lang=en&appid="+auth.openweathermap_api_key,{method:"GET",cache:"no-store"}).then(e=>{if(e.ok)return e.json();throw"Error"}).then(e=>{void 0!==e.main&&void 0!==e.main.temp&&void 0!==e.weather&&(document.querySelector("#weather").textContent=parseFloat(e.main.temp.toFixed(1))+" °C",document.querySelector("#weather-icon").innerHTML='<img src="https://openweathermap.org/img/wn/'+e.weather[0].icon+'@2x.png">')}).catch(e=>{console.log(e)})}function update_title(){document.title="Smart Panel • "+document.querySelector("#date").textContent+" "+document.querySelector("#time").textContent+" • "+document.querySelector("#temperature").textContent+" • "+document.querySelector("#weather").textContent}document.addEventListener("DOMContentLoaded",e=>{get_time(),get_date(),get_temperature(),get_weather(),update_title(),setInterval(()=>{get_time()},1e3),document.querySelector("#light-on").addEventListener("click",e=>{fetch("http://"+auth.light_ip+"/cm?cmnd=Power%20on&user=admin&password="+auth.light_password,{method:"GET",cache:"no-store",mode:"no-cors"})}),document.querySelector("#light-off").addEventListener("click",e=>{fetch("http://"+auth.light_ip+"/cm?cmnd=Power%20off&user=admin&password="+auth.light_password,{method:"GET",cache:"no-store",mode:"no-cors"})})});var day_names=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];